rdf:Description.ns1:select:
SELECT $this
WHERE {
	FILTER NOT EXISTS {
		?shape a sh:PropertyShape ;
			sh:path $this ;
			sh:datatype ?dt .
	}
}

SELECT $this
WHERE {
	FILTER NOT EXISTS {
		?shape a sh:PropertyShape ;
			sh:path $this .
		FILTER ( EXISTS { ?shape sh:class ?c } || EXISTS { ?shape sh:or ?o } )
	}
}

SELECT $this
WHERE {
	FILTER NOT EXISTS {
		$this cas:enumeratedValue ?value .
	}
}

SELECT $this
WHERE {
	FILTER NOT EXISTS {
		?shape a sh:NodeShape ;
			sh:targetClass $this .
	}
}

SELECT $this ?prop
WHERE {
	$this cas:enumeratedProperty ?prop .
	FILTER NOT EXISTS {
		?shape a sh:NodeShape ;
			sh:targetClass $this ;
			sh:property ?propShape .
		?propShape sh:path ?prop .
	}
}

SELECT $this ?link
WHERE {
	$this cas:enumeratedTargetLink ?link .
	FILTER NOT EXISTS {
		?shape a sh:NodeShape ;
			sh:targetClass $this ;
			sh:property ?linkShape .
		?linkShape sh:path ?link .
	}
}

SELECT $this
WHERE {
	FILTER NOT EXISTS {
		?shape a sh:NodeShape ;
			sh:targetClass $this .
	}
}

SELECT $this ?prop
WHERE {
	$this cas:enumeratedProperty ?prop .
	FILTER NOT EXISTS {
		?shape a sh:NodeShape ;
			sh:targetClass $this ;
			sh:property ?propShape .
		?propShape sh:path ?prop .
	}
}

SELECT $this ?link
WHERE {
	$this cas:enumeratedSourceLink ?link .
	FILTER NOT EXISTS {
		?shape a sh:NodeShape ;
			sh:targetClass $this ;
			sh:property ?linkShape .
		?linkShape sh:path ?link .
	}
}

SELECT $this ?link
WHERE {
	$this cas:enumeratedTargetLink ?link .
	FILTER NOT EXISTS {
		?shape a sh:NodeShape ;
			sh:targetClass $this ;
			sh:property ?linkShape .
		?linkShape sh:path ?link .
	}
}
